  const softOnly = !!ih && typeof ih.adsV2InHandSoftOnly === 'function' && ih.adsV2InHandSoftOnly(verdict) // KINEO-ADS-MAO-JUIZ-1610 — reprovou SÓ em "both_objects"/"extra_person" (rótulo e produto certos)
  let packshotsUsed: number | null = null // KINEO-ADS-MAO-JUIZ-1610
  if (ih && step === 'product_photo' && typeof ih.adsV2InHandSoftOnly === 'function') { packshotsUsed = await inHandPackshotsUsed(admin, order, row.idx, ih.ADS_V2_IN_HAND_NO_LABEL_REASON); step = ih.adsV2InHandJudgeStep({ verdict, previousReason: row.reason, packshotsUsed }) } // KINEO-ADS-MAO-JUIZ-1610 — no máximo 1 plano de gente vira packshot por anúncio; leitura que falhou = null (o packshot de antes)
  const judged = () => writeServerEvent({ name: 'ads_v2_product_locked', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, mode: 'in_hand', frame: tag?.frame ?? null, ...(tag?.object ? { object: tag.object } : {}), try: ih ? ih.adsV2InHandTry(row.reason) : null, verdict: verdict ? { ok: verdict.ok, fails: verdict.fails, ...(verdict.unsure?.length ? { unsure: verdict.unsure } : {}), ...(typeof verdict.crop === 'boolean' ? { crop: verdict.crop } : {}) } : null, step, ...(step === 'best' ? { best: softOnly ? 'soft_only' : 'packshot_cap' } : {}), ...(packshotsUsed !== null ? { packshots_used: packshotsUsed } : {}), charged: false } }).catch(() => null) // KINEO-ADS-PRODUTO-NA-MAO-1610 · KINEO-ADS-MAO-AJUSTE-3-1610 — + object no evento · KINEO-ADS-MAO-JUIZ-1610 — + best (por quê) e packshots_used
  if (step === 'keep') { if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: stored })) await judged(); return } // KINEO-ADS-PRODUTO-NA-MAO-1610
  if (step === 'best') { if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: stored })) { await judged(); await shotFallbackEvent(order, row, { to: 'best_photo', reason: softOnly ? 'in_hand_soft' : 'in_hand_packshot_cap', fails: verdict ? verdict.fails : [] }) } return } // KINEO-ADS-MAO-JUIZ-1610 — a melhor foto (esta) em vez do packshot
  if (ih && (step === 'retry' || step === 'no_label')) { // KINEO-ADS-PRODUTO-NA-MAO-1610 — nova foto (a régua da refação da trava: pending sem carimbo)
    const reason = step === 'retry' ? ih.ADS_V2_IN_HAND_RETRY_REASON : ih.ADS_V2_IN_HAND_NO_LABEL_REASON // KINEO-ADS-PRODUTO-NA-MAO-1610
    if (await markShot(admin, row, ['image_submitted'], { status: 'pending', image_request_id: null, image_submit_claimed_at: null, reason })) { await judged(); await shotFallbackEvent(order, row, { to: step === 'retry' ? 'scene_retry' : 'no_label', reason }) } // KINEO-ADS-PRODUTO-NA-MAO-1610
    return // KINEO-ADS-PRODUTO-NA-MAO-1610
  } // KINEO-ADS-PRODUTO-NA-MAO-1610
  if (tag && (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: tag.fallbackUrl, reason: null }))) { await judged(); await shotFallbackEvent(order, row, { to: 'product_photo', reason: 'in_hand_label' }) } // KINEO-ADS-PRODUTO-NA-MAO-1610 — a foto real do produto (o fallback de sempre)
} // KINEO-ADS-PRODUTO-NA-MAO-1610

// ── transições de um plano (todas condicionais ao status de origem) ──────────────────────────────────────────────
async function markShot(admin: SupabaseClient, row: AdsV2ShotRow, from: readonly string[], patch: Record<string, unknown>, stillNull?: 'submit_claimed_at' | 'image_submit_claimed_at'): Promise<boolean> {
  let q = admin.from('ads_v2_shots').update(patch).eq('id', row.id).in('status', from as string[])
  // Carimbo de envio: só vence quem o encontra VAZIO (status sozinho não basta: o 1º ainda está esperando a fal).
  if (stillNull) q = q.is(stillNull, null)
  const r = await q.select('id').maybeSingle()
  return !r.error && !!r.data
}
function failShot(admin: SupabaseClient, row: AdsV2ShotRow, from: readonly string[], reason: string, reasonClass: ReasonClass | string): Promise<boolean> {
  return markShot(admin, row, from, { status: 'failed', reason: reason.slice(0, 200), reason_class: reasonClass })
}

// ── envio (tela, cron e /start) ───────────────────────────────────────────────────────────────────────────────────
/** Plano que nunca passa por IA: `text` (foto parada com zoom) e `user_video` (o vídeo do próprio cliente). */
function neverAi(r: Pick<AdsV2ShotRow, 'kind'>): boolean {
  return r.kind === 'text' || r.kind === 'user_video'
}
function needsImage(r: AdsV2ShotRow): boolean {
  return !neverAi(r) && r.source === 'generated_scene' && !r.image_url && r.status === 'pending' && !r.image_submit_claimed_at
}
function needsVideo(r: AdsV2ShotRow): boolean {
  return !neverAi(r) && !!r.engine && !!r.image_url && (r.status === 'pending' || r.status === 'image_done') && !r.submit_claimed_at
}

/**
 * KINEO-ADS-3-VARIACOES-2026-09-30 — o still da MESMA cena (mesmo idx) na variação A: o estado do pedido A e a imagem
 * mais nova já copiada para o nosso bucket. Leitura que falha = 'unknown' (espera, nunca "a A morreu").
 */
async function loadAnchorStill(admin: SupabaseClient, anchorOrderId: string, userId: string, idx: number): Promise<{ status: string | null; imageUrl: string | null }> {
  const o = await admin.from('ads_v2_orders').select('status').eq('id', anchorOrderId).eq('user_id', userId).maybeSingle()
  if (o.error) return { status: 'unknown', imageUrl: null }
  if (!o.data) return { status: null, imageUrl: null }
  const status = String((o.data as { status: string }).status)
  const s = await admin.from('ads_v2_shots').select('image_url, attempt').eq('order_id', anchorOrderId).eq('idx', idx).not('image_url', 'is', null).order('attempt', { ascending: false }).limit(1)
  if (s.error) return { status: 'unknown', imageUrl: null }
  const url = ((s.data ?? []) as { image_url: string | null }[])[0]?.image_url ?? null
  return { status, imageUrl: url }
}

async function submitImageFor(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<void> {
  // KINEO-ADS-3-VARIACOES-2026-09-30 — variação B/C com gente: a MESMA gente da A. Espera o still da A (ANTES de
