  // O still da A entra como ÚLTIMA referência (as fotos do cliente continuam sendo a referência do lugar e do produto).
  const prompt = basePrompt && anchorUrl ? `${basePrompt} ${ADS_V2_SAME_PERSON_LINE}` : basePrompt
  const refs = anchorUrl && baseRefs.length > 0 ? [...baseRefs, anchorUrl] : baseRefs
  if (anchorOutcome) {
    await writeServerEvent({ name: 'ads_v2_variation_anchor', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, group_id: tag?.group_id ?? null, slot: tag?.slot ?? null, idx: row.idx, outcome: anchorOutcome } })
  }
  if (!prompt || refs.length === 0) {
    await failShot(admin, row, ['pending'], 'scene_without_prompt_or_reference', 'local_policy_gate')
    return
  }
  const inHand = inHandTagOf(order, row.idx) // KINEO-ADS-PRODUTO-NA-MAO-1610 — o plano novo: a foto REAL do produto é a 1ª referência e a pessoa o segura (sem esboço, sem colagem)
  const ihLib = inHand ? await inHandLib() : null // KINEO-ADS-PRODUTO-NA-MAO-1610
  if (inHand && (!ihLib || !(await inHandEnabled(order.user_id)))) { if (await markShot(admin, row, ['pending'], { status: 'image_done', image_url: inHand.fallbackUrl })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: ihLib ? 'in_hand_off' : 'in_hand_lib' }); return } // KINEO-ADS-PRODUTO-NA-MAO-1610 — desligado para a conta = a foto real do produto
  // KINEO-ADS-FIEL-1510 — TRAVA DO PRODUTO: o ESBOÇO (recorte real no lugar, sobre cinza) vira a 1ª referência e a cena volta em PNG
  // KINEO-ADS-FIEL-1510 — para o recorte ser colado de novo sem perda. Falhou o recorte/esboço = o plano anima a FOTO REAL do produto
  // KINEO-ADS-FIEL-1510 — (no ator, que precisa do rosto, o caminho de antes). Sem trava (ou desligada para a conta) = nada muda.
  let sendPrompt = prompt // KINEO-ADS-FIEL-1510
  let sendRefs = refs // KINEO-ADS-FIEL-1510
  const lock = pv ? null : adsV2LockOf(order, row) // KINEO-ADS-FIEL-1510 · KINEO-APRESENTADOR-V2-1710 — o apresentador v2 não passa pela colagem (a foto real é a 2ª referência)
  const srv = lock ? await lockServer() : null // KINEO-ADS-FIEL-1510
  if (lock && srv && (await srv.adsV2ProductLockEnabled(order.user_id).catch(() => false))) { // KINEO-ADS-FIEL-1510
    try { // KINEO-ADS-FIEL-1510
      const layout = await srv.adsV2PrepareLockedScene({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, lock, format: adsV2PlanFormat(order.plan) }) // KINEO-ADS-FIEL-1510
      sendPrompt = lock.mode === 'scene' ? adsV2LockedScenePrompt({ sceneIdx: row.movement_variant, setting: adsV2SettingFromPrompt(planned?.scenePrompt), format: adsV2PlanFormat(order.plan) }) : adsV2ProductLockScenePrompt(prompt, lock.mode) // KINEO-ADS-FIEL-1510 · KINEO-ADS-FIEL-2-1510 — cena de gente: SEM produto, superfície vazia + a proibição
      sendRefs = lock.mode === 'scene' ? [layout, ...adsV2LockSceneRefs({ refs, ids: planned?.referenceFootageIds ?? null, photos: order.photos, lockUrl: lock.url })] : [layout, ...refs] // KINEO-ADS-FIEL-1510 · KINEO-ADS-FIEL-2-1510 — o modelo nunca vê a foto do produto
    } catch (e) { // KINEO-ADS-FIEL-1510
      const why = `lock_prepare:${e instanceof Error ? e.message : String(e)}`.slice(0, 160) // KINEO-ADS-FIEL-1510
      if (lock.mode === 'actor') await shotFallbackEvent(order, row, { to: 'unlocked', reason: why }) // KINEO-ADS-FIEL-1510
      else { if (await markShot(admin, row, ['pending'], { status: 'image_done', image_url: lock.url })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: why }); return } // KINEO-ADS-FIEL-1510
    } // KINEO-ADS-FIEL-1510
  } // KINEO-ADS-FIEL-1510
  if (lock && lock.mode === 'scene' && sendRefs !== refs) sendPrompt = adsV2LockedScenePromptAt({ sceneIdx: row.movement_variant, setting: adsV2SettingFromPrompt(planned?.scenePrompt), format: adsV2PlanFormat(order.plan), side: lockSideOf(order, row) }) // KINEO-ADS-FIEL-4-1510 — a cena já nasce com o CANTO reservado vazio (o MESMO lado em que o recorte será colado) e a gente na metade oposta
  if (inHand && ihLib && inHand.object && sendRefs.length > 0) { const refUrl = await inHandCropLib().then((m) => (m ? m.adsV2InHandReferenceCrop({ userId: order.user_id, cacheKey: order.id, productUrl: sendRefs[0], object: inHand.object }) : null)).catch(() => null); if (refUrl) sendRefs = [refUrl, ...sendRefs.slice(1)] } // KINEO-ADS-MAO-JUIZ-1610 — o que entra na referência entra na cena: o plano da caixa recebe o recorte SÓ da caixa (o do frasco, só o frasco); falhou = a foto inteira
  let outcome
  if (inHand && ihLib && row.reason === ihLib.ADS_V2_IN_HAND_NO_LABEL_REASON) sendPrompt = `${ihLib.adsV2InHandScenePrompt({ frame: 'no_label', settingLine: ihLib.adsV2InHandSettingFrom(planned?.scenePrompt), format: adsV2PlanFormat(order.plan), extraRefs: (planned?.referenceUrls?.length ?? 0) > 1, singleProduct: typeof planned?.scenePrompt === 'string' && planned.scenePrompt.includes(ihLib.ADS_V2_IN_HAND_SINGLE_PRODUCT), object: inHand.object })}${anchorUrl ? ` ${ADS_V2_SAME_PERSON_LINE}` : ''}` // KINEO-ADS-PRODUTO-NA-MAO-1610 — o juiz reprovou 2 vezes: o enquadramento sem o rótulo de frente · KINEO-ADS-MAO-AJUSTE-1610 — + um produto só (como no pedido gravado) · KINEO-ADS-MAO-AJUSTE-3-1610 — + o objeto único do plano
  try {
    outcome = await submitSceneImage({ prompt: sendPrompt, referenceUrls: sendRefs, ...(adsV2PlanFormat(order.plan) !== '9:16' ? { aspect: adsV2PlanFormat(order.plan) } : {}), ...(sendRefs !== refs || inHand ? { outputFormat: 'png' as const } : {}), ...(pv ? { numImages: 4 as const } : {}) }, { userId: order.user_id, orderId: order.id }) // KINEO-APRESENTADOR-V2-1710 — + as 4 opções do apresentador // KINEO-ADS-MELHORIAS-1410 — a cena criada no formato do anúncio · KINEO-ADS-FIEL-1510 — com a trava: o esboço + PNG · KINEO-ADS-MAO-JUIZ-1610 — + o produto na mão em PNG (o juiz recorta o produto gerado)
  } catch (e) {
    // buildSceneImageInput recusou (nada saiu daqui): recusa NOSSA, não refazer.
