async function prepareAndSubmit(admin: SupabaseClient, order: AdsV2OrderRow, leaseToken: string, shots: AdsV2ShotRow[]): Promise<void> {
  const plan = order.plan
  if (!plan || !order.card_url) {
    await failAdsV2Order(admin, order, 'assembly_missing_plan_or_card', '/lib/ads/v2Advance')
    return
  }
  if (adsV2PresenterPlanOf(plan)) { // KINEO-ADS-CENA-2110
    const actor = latestShots(shots).find(isAdsV2PresenterRow) // KINEO-ADS-CENA-2110
    if (!actor || actor.status !== 'done' || !actor.stored_url || !num(actor.measured_seconds)) { await failRequiredUgc(admin, order, 'ugc_presenter_failed:assembly_missing_person'); return } // KINEO-ADS-CENA-2110
  } // KINEO-ADS-CENA-2110
  const language = narrationLanguage(order.language) ?? 'en'
  const mood = SECTOR_MOOD[order.sector ?? 'other'] ?? 'emotional'
  // 1. Música: Lyria (instrumental) copiada para o NOSSO bucket; sem Lyria, a trilha Pixabay de sempre.
  let musicUrl = order.music_url
  // KINEO-APRESENTADOR-V2-AJUSTE-1710 — DE ONDE veio a trilha, no evento da montagem. No T1 (b6823063) o Lyria foi recusado pelo filtro de conteúdo da fal e a
  // KINEO-APRESENTADOR-V2-AJUSTE-1710 — reserva entrou SOZINHA (a curadoria da casa: hustle-02.mp3, clima 'hustle' do setor loja), mas o evento só dizia music:true.
  let musicSource: 'stored' | 'lyria' | 'library' | 'library_swap' | 'none' = musicUrl ? 'stored' : 'none' // KINEO-APRESENTADOR-V2-AJUSTE-1710
  if (!musicUrl) {
    const lyria = await getLyriaMusicUrl(null, mood)
    musicUrl = lyria ? await persistAudioCopy({ userId: order.user_id, name: `adsv2-${order.id}-music`, sourceUrl: lyria }) : null
    if (musicUrl) musicSource = 'lyria' // KINEO-APRESENTADOR-V2-AJUSTE-1710
    if (!musicUrl) musicUrl = await getBackgroundMusicUrl(order.id, mood).catch(() => null)
    if (musicUrl && musicSource === 'none') musicSource = 'library' // KINEO-APRESENTADOR-V2-AJUSTE-1710 — a reserva automática (Lyria recusado/fora do prazo/sem cópia)
    // KINEO-ADS-V2-MUSICA-2026-09-29 — faixa da biblioteca sem 32 s seguidos de música não serve para anúncio:
    // troca por uma aprovada do mesmo clima (lib/ads/v2Music.ts).
    const beforeSwap = musicUrl // KINEO-APRESENTADOR-V2-AJUSTE-1710
    if (musicUrl && !adsV2MusicUsable(musicUrl)) musicUrl = adsV2SwapLibraryTrack(musicUrl, adsV2FallbackTrack(mood, order.id))
    if (musicUrl && musicUrl !== beforeSwap) musicSource = 'library_swap' // KINEO-APRESENTADOR-V2-AJUSTE-1710 — a faixa da biblioteca trocada por uma aprovada do mesmo clima
    if (musicUrl) await admin.from('ads_v2_orders').update({ music_url: musicUrl }).eq('id', order.id).is('music_url', null)
  }
  // 2. Voz MiniMax (a mesma TTS da casa para MiniMax: synthesizeTtsFallback, fal-ai/minimax/speech-2.8-hd), medida
  //    e enviada ao bucket voiceovers. Telefone/site falados por extenso (speakableForTts), como no v1.
  let voiceUrl = order.voice_url
  let voiceSeconds = num(order.voice_seconds)
  const narration = order.narration && typeof plan.narration === 'string' && plan.narration.trim() ? plan.narration.trim() : null
  if (narration && (!voiceUrl || !voiceSeconds)) {
    // KINEO-ATORES-IA-2026-10-13 — aqui o ator já desistiu (senão a voz estaria gravada): a voz do apresentador escolhido,
    // e se ela falhar, a de sempre (o pedido nunca trava por isso). Sem escolha, a chamada de sempre.
    const buf = await adsV2NarrationVoice(order, speakableForTts(adsV2NarrationForTts(narration, adsV2PronounceOf(order.brief)), language), true) // KINEO-ADS-DEMO-UNIVERSO-1410 — sem pronúncia = o texto de sempre
